'use strict';
const routes=window.MAGE_ROUTES,items=window.ITEMS||{},key='gmscw-mage-progress-v1';
let routeKey='mage';try{const saved=localStorage.getItem('gmscw-route');if(routes[saved])routeKey=saved;}catch{}
let tasks=routes[routeKey].tasks.map(t=>({...t,...window.MAGE_GLOSSARY.display[t.id]}));window.MAGE_SELECTED_ROUTE=routeKey;
let progressSync;
const validIds=new Set(Object.values(routes).flatMap(r=>r.tasks.map(t=>t.id)));let completed=new Set(),hideCompleted=false,category='全部';
try{const saved=JSON.parse(localStorage.getItem(key)||'{}');completed=new Set((Array.isArray(saved.completed)?saved.completed:[]).filter(id=>validIds.has(id)));hideCompleted=saved.hideCompleted===true;}catch{storageWarning();}
const $=id=>document.getElementById(id);
function storageWarning(){const e=$('storage-warning');e.hidden=false;e.textContent='浏览器未允许保存进度，当前操作仅在本次打开期间有效。';}
function save(){try{localStorage.setItem(key,JSON.stringify({completed:[...completed],hideCompleted}));}catch{storageWarning();}}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function describe(map){return Object.entries(map).map(([name,n])=>`${name} ×${n}`).join('、');}
function changeTask(id,done){if(progressSync?.isBusy())throw new Error('正在读取或创建进度，请稍候');if(!validIds.has(id)||typeof done!=='boolean')throw new Error('无效的任务或完成状态');if(done)completed.add(id);else completed.delete(id);save();render();progressSync?.changed();}
function changePhase(group,done){if(progressSync?.isBusy())return;for(const task of group){if(done)completed.add(task.id);else completed.delete(task.id);}save();render();progressSync?.changed();}
const nodes=new Map(),phaseNodes=[];
function buildTaskList(){nodes.clear();phaseNodes.length=0;$('task-list').replaceChildren();
for(const phase of [...new Set(tasks.map(t=>t.phase))]){
 const group=tasks.filter(t=>t.phase===phase);const heading=el('div','phase-heading');heading.setAttribute('role','row');const phaseCheck=el('input','phase-check');phaseCheck.type='checkbox';phaseCheck.addEventListener('change',()=>changePhase(group,phaseCheck.checked));const label=el('div','phase-label');const toggle=el('button','phase-toggle',phase);toggle.type='button';toggle.setAttribute('aria-expanded','true');const panel=el('div','phase-tasks');panel.id='phase-tasks-'+phaseNodes.length;const panelClip=el('div','phase-tasks-clip');panel.append(panelClip);toggle.setAttribute('aria-controls',panel.id);toggle.setAttribute('aria-label','展开或收起 '+phase+' 的任务');toggle.addEventListener('click',()=>{const collapsed=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!collapsed));panel.classList.toggle('collapsed',collapsed);panel.inert=collapsed;panel.setAttribute('aria-hidden',String(collapsed));MageGlossary.close();});label.append(phaseCheck,toggle);const count=el('span');heading.append(label,count);MageGlossary.routeButton(heading,group,'阶段地图');$('task-list').append(heading,panel);phaseNodes.push({group,count,phaseCheck,phase});
 for(const t of group){const wrap=el('div','task-wrap');const clip=el('div','task-clip');const row=el('div','task-row');row.setAttribute('role','row');const checkCell=el('div','task-check');checkCell.setAttribute('role','cell');const check=el('input');check.type='checkbox';check.setAttribute('aria-label',`完成 ${MageGlossary.canonicalText(t.title)}`);check.addEventListener('change',()=>changeTask(t.id,check.checked));checkCell.append(check);const level=el('div','task-level',`Lv. ${t.level}`);level.setAttribute('role','cell');const body=el('div');body.setAttribute('role','cell');const title=el('div','task-title');title.append(el('span','task-number',t.id.slice(1)),MageGlossary.taskTitle(t));const place=el('p','task-place',t.place);MageGlossary.routeButton(place,[t]);body.append(title,place,el('div','task-goal',t.goal));
 if(Object.keys(t.gain).length)body.append(el('div','task-materials','获得 / 收齐：'+describe(t.gain)));
 if(Object.keys(t.cost).length)body.append(el('div','task-materials minus','消耗：'+describe(t.cost)));
 if(t.note)body.append(el('p','task-note',t.note));row.append(checkCell,level,body);clip.append(row);wrap.append(clip);panelClip.append(wrap);nodes.set(t.id,{wrap,check});}
}
}
function setRoute(value){if(!routes[value]||progressSync?.isBusy())return;routeKey=value;window.MAGE_SELECTED_ROUTE=value;tasks=routes[value].tasks.map(t=>({...t,...window.MAGE_GLOSSARY.display[t.id]}));try{localStorage.setItem('gmscw-route',value);}catch{}MageGlossary.close();buildTaskList();render();}
function chips(target,label,values,kind){const e=$(target);e.replaceChildren();e.className='materials '+kind;if(!values||!Object.keys(values).length)return;e.append(el('span','material-label',label));for(const [name,n] of Object.entries(values))e.append(el('span','chip',`${name} ×${n}`));}
function renderInventory(s){const all=Object.entries(s.projected).filter(([,n])=>n>0);const visible=all.filter(([name])=>category==='全部'||(items[name]?.category||'装备')===category);const grid=$('inventory-grid');grid.replaceChildren();for(const [name,n] of visible){const item=items[name];const cell=el('button','slot has-item');cell.title=`${name} ×${n}${item?.english?' · '+item.english:''}`;cell.setAttribute('aria-label',cell.title);const term=MAGE_GLOSSARY.terms.find(t=>t.kind==='item'&&t.zh===name);if(term){cell.classList.add('game-term');cell.dataset.term=term.id;cell.setAttribute('aria-haspopup','dialog');cell.setAttribute('aria-controls','name-popover');cell.setAttribute('aria-expanded','false');cell.removeAttribute('title');}if(item){const img=el('img');img.src=item.path;img.alt=name;img.width=32;img.height=32;img.addEventListener('error',()=>{img.remove();cell.prepend(el('span','unknown',name));},{once:true});cell.append(img);}else cell.append(el('span','unknown',name));cell.append(el('span','quantity',String(n)));const detail=()=>{$('inventory-detail').textContent=`${name} ×${n}${item?.note?' · '+item.note:''}`;MageGlossary.decorate($('inventory-detail'));};cell.addEventListener('click',detail);grid.append(cell);}const slots=Math.max(20,Math.ceil(visible.length/5)*5);for(let n=visible.length;n<slots;n++)grid.append(el('div','slot'));$('inventory-count').textContent=`${all.length} 种道具${category==='全部'?'':` · 本栏 ${visible.length}`}`;$('inventory-detail').textContent=all.length?'选择道具查看详情':'当前没有需要保留的材料';$('deficit').textContent=s.deficits.length?'材料缺口（检查是否跳过收集）：'+s.deficits.map(([k,n])=>`${k} ${-n}`).join('、'):'';}
function render(){document.querySelectorAll('[data-route]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.route===routeKey)));$('route-label').textContent=routes[routeKey].label+' · 开荒手册';const exportLink=document.querySelector('.export');exportLink.href=routeKey==='mage'?'GMSCW_Mage_Task.xlsx':'GMSCW_'+routeKey+'_Task.xlsx';const s=MageLedger.snapshot(tasks,completed);$('progress-label').textContent=`${s.count} / ${tasks.length} 已完成`;$('progress').style.width=`${s.count/tasks.length*100}%`;$('step-badge').textContent=s.current?`${s.current.id.slice(1)} / ${tasks.length}`:'COMPLETE';$('current-phase').textContent=s.current?.phase||'冒险仍在继续';$('current-title').replaceChildren(s.current?MageGlossary.taskTitle(s.current):document.createTextNode('这段旅程，完成了。'));$('current-place').textContent=s.current?.place||routes[routeKey].label+'路线已全部勾选';$('current-goal').textContent=s.current?.goal||'你的任务记录和剩余材料已保存在当前浏览器。可以取消下方勾选，回看任一步。';$('current-note').textContent=s.current?.note||'';chips('current-cost','需要消耗',s.current?.cost,'cost');chips('current-gain','获得 / 收齐',s.current?.gain,'gain');$('complete-current').disabled=!s.current;$('forecast-level').textContent=s.level;const projectedDone=new Set(completed);if(s.current)projectedDone.add(s.current.id);$('forecast-job').textContent=projectedDone.has(routes[routeKey].secondJob)?'二转'+(routeKey==='mage'?'法师':routes[routeKey].label):projectedDone.has(routes[routeKey].firstJob)?routes[routeKey].label:'初心者';$('hide-completed').setAttribute('aria-checked',String(hideCompleted));for(const t of tasks){const {wrap,check}=nodes.get(t.id),done=completed.has(t.id),fold=done&&hideCompleted;check.checked=done;wrap.classList.toggle('completed',done);wrap.classList.toggle('next',t===s.current);wrap.classList.toggle('folded',fold);wrap.inert=fold;wrap.setAttribute('aria-hidden',String(fold));}for(const {group,count,phaseCheck,phase}of phaseNodes){const done=group.filter(t=>completed.has(t.id)).length;count.textContent=`${done} / ${group.length}`;phaseCheck.checked=done===group.length;phaseCheck.indeterminate=done>0&&done<group.length;const hint=done===group.length?'取消完成此阶段所有任务':'一键完成此阶段所有任务';phaseCheck.title=hint;phaseCheck.setAttribute('aria-label',phase+'：'+hint);}$('all-hidden').hidden=!(hideCompleted&&s.count===tasks.length);renderInventory(s);MageTraining.render(s.current);if(s.current)MageGlossary.routeButton($('current-place'),[s.current]);MageGlossary.decorate(document.querySelector('main'));}
$('complete-current').addEventListener('click',()=>{const s=MageLedger.snapshot(tasks,completed);if(s.current)changeTask(s.current.id,true);});$('hide-completed').addEventListener('click',()=>{hideCompleted=!hideCompleted;save();render();});document.querySelectorAll('[data-category]').forEach(button=>button.addEventListener('click',()=>{category=button.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});render();}));
document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>setRoute(b.dataset.route)));
buildTaskList();render();
progressSync=window.setupMageSync({getCompleted:()=>[...completed].sort(),replaceCompleted(ids){completed=new Set(ids.filter(id=>validIds.has(id)));save();render();}});
if(document.modelContext?.registerTool){const abort=new AbortController();addEventListener('pagehide',()=>abort.abort(),{once:true});const specs=[{name:'read_mage_progress',description:'读取当前所选职业路线的任务、已完成步骤及预计背包。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return MageLedger.snapshot(tasks,completed);}},{name:'set_mage_task_completed',description:'设置单个任务已完成或未完成，并立即更新页面与本机保存的材料账本。',inputSchema:{type:'object',properties:{taskId:{type:'string'},completed:{type:'boolean'}},required:['taskId','completed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.taskId!=='string'||typeof input.completed!=='boolean')throw new Error('需要有效的 taskId 与布尔 completed');changeTask(input.taskId,input.completed);return {taskId:input.taskId,completed:input.completed,nextTask:MageLedger.snapshot(tasks,completed).current?.id||null};}}];for(const spec of specs){try{Promise.resolve(document.modelContext.registerTool(spec,{signal:abort.signal})).catch(()=>{});}catch{}}}
